#!/usr/bin/env node
// Builds src/data/arabic/qasas-translation.js from
// scripts/qasas-translation-source.txt.
//
// To add a chapter: append it to the source file in the same format, then run
//   npm run build:qasas-bank
// and review the generated file. See the header of the source file for the
// format.

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const sourcePath = resolve(here, 'qasas-translation-source.txt');
const outputPath = resolve(here, '../src/data/arabic/qasas-translation.js');

const MACROS = {
  $IBR: ['Ibrahim', 'Ibraheem', 'Ibraahim', 'Ibraaheem', 'Ibrahiim', 'Abraham'],
  $AZAR: ['Azar', 'Aazar', 'Azer', 'Aazer', 'Aazaar'],
  $ALLAH: ['Allah', 'Allaah', 'God'],
};

function fail(lineNumber, message) {
  throw new Error(`qasas-translation-source.txt:${lineNumber}: ${message}`);
}

export function parseSource(text) {
  const chapters = [];
  const sentences = [];
  let chapter = null;
  let sentence = null;

  const finishSentence = (lineNumber) => {
    if (!sentence) return;
    if (!sentence.en) fail(lineNumber, `sentence "${sentence.ar}" has no "=" translation line`);
    if (sentence.words.length === 0) fail(lineNumber, `sentence "${sentence.ar}" has no word lines`);
    sentences.push(sentence);
    sentence = null;
  };

  text.split(/\r?\n/).forEach((rawLine, lineIndex) => {
    const lineNumber = lineIndex + 1;
    const line = rawLine.trim();
    if (!line || (line.startsWith('#') && !line.startsWith('##'))) return;

    if (line.startsWith('##')) {
      finishSentence(lineNumber);
      const [number, title, titleAr] = line.slice(2).split('|').map((part) => part.trim());
      const chapterNumber = Number(number);
      if (!Number.isInteger(chapterNumber)) fail(lineNumber, 'chapter header needs a number');
      chapter = { chapter: chapterNumber, title, titleAr, count: 0 };
      chapters.push(chapter);
      return;
    }

    if (line.startsWith('>')) {
      finishSentence(lineNumber);
      if (!chapter) fail(lineNumber, 'sentence before any chapter header');
      chapter.count += 1;
      sentence = {
        id: `QSS-C${chapter.chapter}-S${String(chapter.count).padStart(2, '0')}`,
        topic: 'QSS',
        type: 'qasasTranslation',
        chapter: chapter.chapter,
        chapterTitle: chapter.title,
        ar: line.slice(1).trim(),
        en: '',
        words: [],
      };
      return;
    }

    if (!sentence) fail(lineNumber, 'line outside a sentence');

    if (line.startsWith('=')) {
      sentence.en = line.slice(1).trim();
      return;
    }

    const separator = line.indexOf(' : ');
    if (separator === -1) fail(lineNumber, 'word line needs "arabic : answer | answer"');
    let ar = line.slice(0, separator).trim();
    const answers = line.slice(separator + 3).trim();
    const optional = ar.startsWith('?');
    if (optional) ar = ar.slice(1).trim();

    const word = { ar };
    if (answers.startsWith('(')) {
      word.en = [];
      word.note = answers.replace(/^\(|\)$/g, '');
    } else {
      word.en = answers
        .split('|')
        .map((answer) => answer.trim())
        .flatMap((answer) => MACROS[answer] || [answer])
        .filter(Boolean);
      if (word.en.length === 0) fail(lineNumber, `no answers for ${ar}`);
    }
    if (optional) word.optional = true;
    sentence.words.push(word);
  });

  finishSentence(text.split(/\r?\n/).length);
  return { chapters, sentences };
}

function literal(value) {
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

function renderWord(word) {
  const parts = [`ar: ${literal(word.ar)}`, `en: [${word.en.map(literal).join(', ')}]`];
  if (word.optional) parts.push('optional: true');
  if (word.note) parts.push(`note: ${literal(word.note)}`);
  return `      { ${parts.join(', ')} },`;
}

export function renderModule({ chapters, sentences }) {
  const chapterLines = chapters.map(
    (chapter) =>
      `  { chapter: ${chapter.chapter}, title: ${literal(chapter.title)}, titleAr: ${literal(chapter.titleAr)} },`
  );
  const sentenceBlocks = sentences.map((sentence) =>
    [
      '  {',
      `    id: ${literal(sentence.id)},`,
      `    topic: ${literal(sentence.topic)},`,
      `    type: ${literal(sentence.type)},`,
      `    chapter: ${sentence.chapter},`,
      `    chapterTitle: ${literal(sentence.chapterTitle)},`,
      `    ar: ${literal(sentence.ar)},`,
      `    en: ${literal(sentence.en)},`,
      '    words: [',
      ...sentence.words.map(renderWord),
      '    ],',
      '  },',
    ].join('\n')
  );

  return `// GENERATED by scripts/build-qasas-translation-bank.mjs from
// scripts/qasas-translation-source.txt. Edit the source file, then run
// \`npm run build:qasas-bank\`. Do not edit this file by hand.
//
// Qasas an-Nabiyyin sentence translation bank. Each sentence is graded word by
// word: \`words[].en[0]\` is the textbook meaning, the rest are accepted
// alternatives. A leading "a"/"an"/"the" on an answer is required. Words marked
// \`optional\` are not counted against the student when left out.

export const QASAS_TRANSLATION_CHAPTERS = [
${chapterLines.join('\n')}
];

export const qasasTranslationQuestions = [
${sentenceBlocks.join('\n')}
];
`;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const parsed = parseSource(readFileSync(sourcePath, 'utf8'));
  writeFileSync(outputPath, renderModule(parsed));
  console.log(
    `Wrote ${parsed.sentences.length} sentences across ${parsed.chapters.length} chapters to ${outputPath}`
  );
}
